"""
读取 "座舱意图训练表-小程序.csv" 中的 query 与 intent，
通过调用 master_agent_intent_model 接口进行预测，
并统计模型预测的准确率。

用法：
 python validate_intent_accuracy.py [csv_path] [--limit N] [--workers N] [--output result.csv]
"""

import argparse
import csv
import json
import os
import sys
import time
import uuid
from concurrent.futures import ThreadPoolExecutor, as_completed

import requests


API_URL = "https://devgw.tai.qq.com/tacs_llm_scenariox_agent_model_api_svc/v1/chat/completions"
AUTH_TOKEN = "Bearer 7auGXNATFSKl7dF"

SYSTEM_PROMPT = """
 你是一个车载智能助手，负责准确识别用户语音指令的真实意图。请从以下类别中选择最匹配的一项：[
 {
 "agent_name": "sights",
 "description": "你是一个专业的景点助手，能够根据用户需求提供景点推荐服务"
 },
 {
 "agent_name": "parking",
 "description": "你是一个停车费帮缴助手，支持完整的停车费缴纳流程,如：帮我交一下停车费，我的车牌号是鄂A18160"
 },
 {
 "agent_name": "puscene",
 "description": "你是资深的取号订座助手，帮助用户通过语音完成取号订座,如：帮我订个座、帮我取个号"
 },
 {
 "agent_name": "meituan",
 "description": "你是一个专业的美团点单助手，支持完整的点单流程，支持在美团小程序内的一切点单流程 如：美团点单"
 },
 {
 "agent_name": "tc_travel",
 "description": "你是一个专业的同程旅行助手，支持酒店，火车票，飞机票，景点门票等查询、预订等相关服务 如：查询附近酒店、帮我订酒店"
 },
 {
 "agent_name": "video",
 "description": "你是一个专业的视频智能助手，能够根据用户需求提供视频推荐、影视搜索、短剧搜索、视频问答等服务。"
 },
 {
 "agent_name": "luckin",
 "description": "你是一个专业的瑞幸点单助手，支持完整的点单流程，如：瑞幸咖啡"
 },
 {
 "agent_name": "chat",
 "description": "通用闲聊与信息查询助手，支持天气、旅游、人物、网站、实时与历史信息查询，不支持车辆控制和多媒体播放。"
 },
 {
 "agent_name": "news",
 "description": "新闻资讯助手，提供热点、分类、地区、健康等新闻内容，支持早晚报和个性化推荐。"
 },
 {
 "agent_name": "music",
 "description": "音乐助手，支持歌曲搜索、推荐、识别、播放及音乐相关问答。"
 },
 {
