 },
 {
 "agent_name": "travel_plan",
 "description": "旅游规划助手，提供行程规划、出游推荐、酒店推荐及导航服务。"
 },
 {
 "agent_name": "maoyan",
 "description": "你是一个专业的电影助手，在猫眼电影小程序，能够根据用户需求帮助用户购买电影票，明确购买意图，如：我要买电影票"
 },
 {
 "agent_name": "starbucks",
 "description": "你是一个专业的星巴克点单助手，支持完整的点单流程，如：星巴克、星咖啡、星冰乐"
 },
 {
 "agent_name": "retail",
 "description": "你是一个专业的随行点单助手，支持完整的点单流程，如：星巴克、星咖啡、星冰乐"
 },
 {
 "agent_name": "health",
 "description": "你是一位专业的日常健康科普问答助手，你可以根据客户提问的问题，查询腾讯医典，并根据已知内容给出专业的回复"
 }
]
 要求： 
 - 输出必须是上述类别agent_name之一，不得添加解释、标点或换行 
 - 若用户请求涉及多个意图，选择最核心或最先提及的意图 
 - 只用输出一个符合要求的类别名称 
 - 若无法明确归类到这几类，则输出"chat"
 """


def build_payload(query: str) -> dict:
 """构造请求体"""
 return {
 "trace_id": f"{int(time.time() * 1000)}_{uuid.uuid4().hex[:8]}",
 "app_id": "test",
 "unique_id": f"mock_{uuid.uuid4().hex}",
 "channel_id": "009000",
 "agent_name": "master_agent",
 "query_id": uuid.uuid4().hex,
 "model": "master_agent_intent_model",
 "stream": False,
 "messages": [
 {"role": "system", "content": SYSTEM_PROMPT},
 {
 "role": "user",
 "content": [{"type": "text", "text": query}],
 },
 ],
 "temperature": 0.1,
 "top_p": 1.0,
 "max_tokens": 2048,
 "wsid": "12146",
 "chat_template_kwargs": {"enable_thinking": False},
 "openai_infer": True,
 }


def call_api(query: str, timeout: int = 30, retry: int = 2) -> str:
 """调用模型接口，返回预测的 agent_name；失败时返回 'ERROR'"""
 headers = {
 "Accept": "*/*",
 "Authorization": AUTH_TOKEN,
 "Content-Type": "application/json",
 "User-Agent": "PostmanRuntime-ApipostRuntime/1.1.0",
 }
 payload = build_payload(query)
 last_err = ""
 for attempt in range(retry + 1):
 try:
 resp = requests.post(
 API_URL, headers=headers, json=payload, timeout=timeout
 )
 if resp.status_code != 200:
 last_err = f"HTTP {resp.status_code}: {resp.text[:200]}"
 continue
 data = resp.json()
 # 兼容 OpenAI 格式
 try:
 content = data["choices"][0]["message"]["content"]
 except Exception:
 last_err = f"Bad response: {str(data)[:200]}"
 continue
 if isinstance(content, list):
 # content 可能是数组形式
 texts = []
 for item in content:
 if isinstance(item, dict) and "text" in item:
 texts.append(item["text"])
 content = "".join(texts)
 return str(content).strip()
 except Exception as e:
 last_err = f"{type(e).__name__}: {e}"
 time.sleep(0.5)
 return f"ERROR::{last_err}"


def load_dataset(csv_path: str):
 """加载 CSV，返回 [(query, expected_intent), ...]"""
 samples = []
 with open(csv_path, "r", encoding="utf-8") as f:
 reader = csv.DictReader(f)
 for row in reader:
 query = (row.get("query") or "").strip()
 intent = (row.get("intent") or "").strip()
 if not query or not intent:
 continue
 samples.append((query, intent))
 return samples


def evaluate(csv_path: str, limit: int = 0, workers: int = 8, output: str = ""):
 samples = load_dataset(csv_path)
 if limit > 0:
 samples = samples[:limit]
 total = len(samples)
 if total == 0:
 print("没有可用样本，请检查 CSV 文件。")
 return

 print(f"开始验证，共 {total} 条样本，并发数：{workers}")
 print(f"接口：{API_URL}")
 print(f"模型：master_agent_intent_model")
 print("-" * 80)

 results = [None] * total
 correct_cnt = 0
 error_cnt = 0
 done_cnt = 0
 intent_stat = {} # intent -> [correct, total]

 def task(idx, q, expected):
 pred = call_api(q)
 return idx, q, expected, pred

 t0 = time.time()
 with ThreadPoolExecutor(max_workers=workers) as ex:
 futures = [
 ex.submit(task, i, q, intent) for i, (q, intent) in enumerate(samples)
 ]
 for fut in as_completed(futures):
 idx, q, expected, pred = fut.result()
 results[idx] = (q, expected, pred)
 done_cnt += 1
 if pred.startswith("ERROR"):
 error_cnt += 1
 else:
 stat = intent_stat.setdefault(expected, [0, 0])
 stat[1] += 1
 if pred == expected:
 correct_cnt += 1
 stat[0] += 1
 if done_cnt % 20 == 0 or done_cnt == total:
 elapsed = time.time() - t0
 acc = correct_cnt / max(done_cnt - error_cnt, 1)
 print(
 f"进度: {done_cnt}/{total} 正确: {correct_cnt} "
 f"错误调用: {error_cnt} 当前准确率: {acc:.2%} "
 f"用时: {elapsed:.1f}s"
 )

 valid = total - error_cnt
 acc = correct_cnt / valid if valid > 0 else 0.0
 print("=" * 80)
 print(f"总样本: {total}, 有效: {valid}, 接口失败: {error_cnt}")
 print(f"预测正确: {correct_cnt}, 整体准确率: {acc:.2%}")
 print("-" * 80)
 print("各意图分项准确率：")
 for intent_name, (c, t) in sorted(
 intent_stat.items(), key=lambda x: -x[1][1]
 ):
 a = c / t if t > 0 else 0.0
 print(f" {intent_name:<15s} {c}/{t} ({a:.2%})")

 # 保存详细结果
 if not output:
 output = os.path.join(
 os.path.dirname(os.path.abspath(csv_path)),
 "intent_validation_result.csv",
 )
 with open(output, "w", encoding="utf-8", newline="") as f:
 writer = csv.writer(f)
 writer.writerow(["query", "expected", "predicted", "is_correct"])
 for r in results:
 if not r:
 continue
 q, exp, pred = r
 writer.writerow([q, exp, pred, "1" if pred == exp else "0"])
 print(f"\n详细结果已保存至：{output}")


def main():
 parser = argparse.ArgumentParser(description="意图识别模型准确率验证")
 parser.add_argument(
 "csv_path",
 nargs="?",
 default=os.path.join(
 os.path.dirname(os.path.abspath(__file__)),
 "座舱意图训练表-小程序.csv",
 ),
 help="测试集 CSV 路径",
 )
 parser.add_argument("--limit", type=int, default=0, help="只跑前N条，0表示全部")
 parser.add_argument("--workers", type=int, default=8, help="并发线程数")
 parser.add_argument("--output", type=str, default="", help="结果输出CSV路径")
 args = parser.parse_args()

 if not os.path.exists(args.csv_path):
 print(f"文件不存在: {args.csv_path}")
 sys.exit(1)
 evaluate(args.csv_path, args.limit, args.workers, args.output)


if __name__ == "__main__":
 main()
