import json
p = '/Users/rwardzhang/PycharmProjects/master_agent_qc/coffee/coffee_train.jsonl'
total = 0; bad = 0
with open(p, 'r', encoding='utf-8') as f:
 for i, line in enumerate(f, 1):
 total += 1
 try:
 json.loads(line)
 except Exception as e:
 bad += 1
 print(f'BAD line {i}: {e}')
print(f'total={total}, bad={bad}')

# 抽样：每个标签各取 1 条单轮 + 1 条多轮
import random
random.seed(1)
buckets = {'meituan': [], 'luckin': [], 'starbucks': []}
with open(p, 'r', encoding='utf-8') as f:
 for line in f:
 d = json.loads(line)
 lbl = d['messages'][-1]['content']
 if lbl in buckets:
 buckets[lbl].append(d)

for lbl, arr in buckets.items():
 single = [d for d in arr if len(d['messages']) == 3] # system + 1 user + label
 multi = [d for d in arr if len(d['messages']) > 3]
 print('='*80)
 print(f'### {lbl}: total={len(arr)}, single={len(single)}, multi={len(multi)}')
 if single:
 print('-- 单轮示例 --')
 print(json.dumps(random.choice(single), ensure_ascii=False, indent=2))
 if multi:
 print('-- 多轮示例 --')
 print(json.dumps(random.choice(multi), ensure_ascii=False, indent=2))
